\[ab + bc + cd + da.\]

Put your final answer within \boxed{}.

#include <bits/stdc++.h>
using namespace std;

int main() {
    int a, b, c, d;
    cin >> a >> b >> c >> d;
    int max_value = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                for (int l = 0; l < 4; l++) {
                    if (i != j && i != k && i != l && j != k && j != l && k != l) {
                        int value = a * b + b * c + c * d + d * a;
                        max_value = max(max_value, value);
                    }
                }
            }
        }
    }
    cout << max_value << endl;
    return 0;
}

